function matchParen(source: string, open: number): number {
    let depth = 0;
    let quote: '"' | "'" | "`" | null = null;
    for (let i = open; i < source.length; i++) {
        const ch = source[i];
        if (quote) {
            if (ch === "\\") {
                i++;
                continue;
            }
            if (ch === quote) quote = null;
            continue;
        }
        if (ch === '"' || ch === "'" || ch === "`") {
            quote = ch;
            continue;
        }
        if (ch === "(") depth++;
        else if (ch === ")") {
            depth--;
            if (depth === 0) return i;
        }
    }
    throw new Error(`unbalanced call near ${open}`);
}

function argumentSpans(source: string, callee: string): string[] {
    const spans: string[] = [];
    let i = 0;
    while (i < source.length) {
        const at = source.indexOf(callee, i);
        if (at < 0) break;
        const before = at > 0 ? source[at - 1] : "";
        if (before && /[A-Za-z0-9_$]/.test(before)) {
            i = at + callee.length;
            continue;
        }
        let j = at + callee.length;
        while (j < source.length && /\s/.test(source[j] ?? "")) j++;
        if (source[j] !== "(") {
            i = at + callee.length;
            continue;
        }
        const end = matchParen(source, j);
        spans.push(source.slice(j + 1, end));
        i = end + 1;
    }
    return spans;
}

function extractFunction(source: string, name: string): string {
    const marker = `export async function ${name}`;
    const start = source.indexOf(marker);
    if (start < 0) throw new Error(`missing ${name}`);
    let i = start + marker.length;
    while (source[i] !== "(") i++;
    i = matchParen(source, i) + 1;
    let angle = 0;
    let brace = 0;
    let quote: '"' | "'" | "`" | null = null;
    for (; i < source.length; i++) {
        const ch = source[i];
        if (quote) {
            if (ch === "\\") {
                i++;
                continue;
            }
            if (ch === quote) quote = null;
            continue;
        }
        if (ch === '"' || ch === "'" || ch === "`") {
            quote = ch;
            continue;
        }
        if (ch === "<") angle++;
        else if (ch === ">") angle = Math.max(0, angle - 1);
        else if (ch === "{") {
            if (angle === 0 && brace === 0) {
                let depth = 0;
                let bodyQuote: '"' | "'" | "`" | null = null;
                for (let j = i; j < source.length; j++) {
                    const bodyCh = source[j];
                    if (bodyQuote) {
                        if (bodyCh === "\\") {
                            j++;
                            continue;
                        }
                        if (bodyCh === bodyQuote) bodyQuote = null;
                        continue;
                    }
                    if (bodyCh === '"' || bodyCh === "'" || bodyCh === "`") {
                        bodyQuote = bodyCh;
                        continue;
                    }
                    if (bodyCh === "{") depth++;
                    else if (bodyCh === "}") {
                        depth--;
                        if (depth === 0) return source.slice(start, j + 1);
                    }
                }
                throw new Error(`unbalanced ${name}`);
            }
            brace++;
        } else if (ch === "}") brace = Math.max(0, brace - 1);
    }
    throw new Error(`no body for ${name}`);
}

function passesInputMillSide(fnSource: string, callee: string): boolean {
    return argumentSpans(fnSource, callee).some((span) => span.includes("args.input.millSide"));
}

function procedureSlice(source: string, name: string): string {
    const at = source.indexOf(`\n    ${name}:`);
    if (at < 0) throw new Error(`missing procedure ${name}`);
    const rest = source.slice(at + 1);
    const next = rest.slice(1).search(/\n    [A-Za-z0-9]+:/);
    return next < 0 ? rest : rest.slice(0, next + 1);
}

function productDiff(repo: string): string[] {
    const head = execFileSync("git", ["rev-parse", "HEAD"], { cwd: repo, encoding: "utf8" }).trim();
    const mergeBase = execFileSync("git", ["merge-base", BASE_SHA, head], { cwd: repo, encoding: "utf8" }).trim();
    const lines = (args: string[]) =>
        execFileSync("git", args, { cwd: repo, encoding: "utf8" })
            .split("\n")
            .map((line) => line.trim())
            .filter(Boolean);
    const names = [
        ...lines(["diff", "--name-only", mergeBase, head]),
        ...lines(["diff", "--name-only", "HEAD"]),
        ...lines(["ls-files", "--others", "--exclude-standard"]),
    ];
    return [...new Set(names)].filter(
        (path) =>
            !path.startsWith("validation/mill_side_server_gates/") &&
            !path.split("/").includes("node_modules") &&
            path !== "vertex/server/src/lib/cnc-mill-job.js",
    );
}

function addedLines(repo: string): string[] {
    const head = execFileSync("git", ["rev-parse", "HEAD"], { cwd: repo, encoding: "utf8" }).trim();
    const mergeBase = execFileSync("git", ["merge-base", BASE_SHA, head], { cwd: repo, encoding: "utf8" }).trim();
    const chunks = [
        execFileSync("git", ["diff", "-U0", mergeBase, head], { cwd: repo, encoding: "utf8" }),
        execFileSync("git", ["diff", "-U0", "HEAD"], { cwd: repo, encoding: "utf8" }),
    ];
    const added: string[] = [];
    for (const chunk of chunks) {
        for (const line of chunk.split("\n")) {
            if (line.startsWith("+++")) continue;
            if (line.startsWith("+")) added.push(line.slice(1));
        }
    }
    return added;
}

function redact(text: string): string {
    return text
        .split("\n")
        .filter((line) => !/api[_-]?key|bearer|token/i.test(line))
        .filter((line) => !/lovelace|\bada\b/i.test(line))
        .join("\n");
}

