async function loadProduct(repo: string): Promise<Loaded> {
    execFileSync(process.execPath, ["scripts/bundle-cnc-mill-job.mjs"], {
        cwd: join(repo, "vertex"),
        stdio: "inherit",
    });
    const url = (rel: string) => pathToFileURL(join(repo, rel)).href;
    const store = await import(url("vertex/src/stores/design-store.ts"));
    const settingsMod = await import(url("vertex/shared/design-settings.ts"));
    const design = store.createDesignWithStockPlaceholder();
    design.method = "milling_3axis";
    design.usMenSize = 9;
    design.thicknessMm = THICKNESS_UNMARKED_MM;
    if (design.paired) {
        design.paired.leftMethod = "milling_3axis";
        design.paired.rightMethod = "milling_3axis";
        design.paired.leftThicknessMm = THICKNESS_UNMARKED_MM;
        design.paired.rightThicknessMm = THICKNESS_UNMARKED_MM;
    }
    const settingsJson = JSON.parse(JSON.stringify(settingsMod.designSettingsEnvelope(design))) as unknown;
    const doc = {
        id: DESIGN_ID,
        pattern: design.pattern,
        method: design.method,
        thicknessMm: design.thicknessMm,
        linked: design.corrections.linked,
        unit: design.corrections.unit,
        createdAt: "2026-11-15T00:00:00.000Z",
        updatedAt: "2026-11-15T00:00:00.000Z",
        settingsJson,
    };
    const runner = await import(url("vertex/server/src/lib/cnc-mill-runner.ts"));
    const orderSides = await import(url("vertex/src/lib/cnc/order-sides.ts"));
    const thicknessMod = await import(url("vertex/src/lib/geometry/shape-finish-modifiers.ts"));
    const names = await import(url("vertex/shared/export-filename.ts"));
    const identityMod = await import(url("vertex/server/src/lib/cad-operator-production.ts"));
    const cadAuth = await import(url("vertex/server/src/auth/cad-operator.ts"));
    const recipeMod = await import(url("vertex/shared/print-recipe/print-recipe.ts"));
    const profileMod = await import(url("vertex/src/lib/cnc/profile.ts"));
    const envelope = await import(url("vertex/src/lib/cnc/envelope.ts"));
    const shoe = await import(url("vertex/src/lib/geometry/shoe-size.ts"));
    const documents = await import(url("vertex/src/features/clients/design-document.ts"));
    const hydrated = documents.designStateFromDocument(doc);
    const profile = profileMod.IDAHO_PROFILE;
    const snap: ProfileSnap = {
        id: profile.id,
        strategy: profile.strategy,
        strategyContour: profile.strategyContour,
        fileExtension: profile.fileExtension,
        toolpathCutter: {
            diameterMm: profile.toolpathCutter.diameterMm,
            type: profile.toolpathCutter.type,
            rpm: profile.toolpathCutter.rpm,
        },
        contourCutter: {
            diameterMm: profile.contourCutter.diameterMm,
            type: profile.contourCutter.type,
            rpm: profile.contourCutter.rpm,
        },
        topFeeds: { ...profile.topFeeds },
        bottomFeeds: { ...profile.bottomFeeds },
        stepoverBallMm: profile.stepoverBallMm,
        stepoverFlatMm: profile.stepoverFlatMm,
        layeredEnabled: profile.layeredEnabled,
        layeredMm: profile.layeredMm,
        sampleMm: profile.sampleMm,
        chordTolMm: profile.chordTolMm,
        tableWidthMm: profile.tableWidthMm,
        tableLengthMm: profile.tableLengthMm,
        materialHeightMm: profile.materialHeightMm,
        pockets: profile.pockets.map((pocket: { x: number; y: number; width: number; length: number }) => ({
            ...pocket,
        })),
    };
    const readStored = settingsMod.readStoredDesignSettings as (raw: unknown) => { printRecipe?: unknown } | null;
    return {
        prepare: runner.prepareHeadlessMillDesign,
        buildServer: runner.buildHeadlessMillCncGcode,
        buildBrowser: async (input) => {
            const mill = await import(url("vertex/src/lib/cnc/mill-job.ts"));
            return mill.buildMillCncGcode(input);
        },
        internalSide: orderSides.internalSideForPhysicalFoot,
        normalize: orderSides.normalizeMillSide,
        thickness: thicknessMod.thicknessMmForDesignSide,
        filename: names.cncPairGcodeFilename,
        canonicalMaterial: names.canonicalExportMaterialName,
        identity: identityMod.cadOperatorManufacturingIdentity,
        presetId: cadAuth.CNC_GCODE_PRESET_ID as string,
        recipe: (raw) => {
            const settings = readStored(raw);
            const parsed = recipeMod.printRecipeV1Schema.safeParse(settings?.printRecipe);
            return parsed.success ? parsed.data : recipeMod.migratePrintRecipe(undefined);
        },
        profile: snap,
        clearanceMm: envelope.ENVELOPE_CLEARANCE_MM as number,
        layout15: shoe.insoleLayoutForUsMenSize(15),
        doc,
        settingsJson,
        hydrated,
        requestSource: readFileSync(join(repo, "vertex/server/src/routers/cad-operator-generate.ts"), "utf8"),
        manufacturingSource: readFileSync(join(repo, "vertex/server/src/routers/manufacturing.ts"), "utf8"),
        runnerSource: readFileSync(join(repo, "vertex/server/src/lib/cnc-mill-runner.ts"), "utf8"),
        millJobSource: readFileSync(join(repo, "vertex/src/lib/cnc/mill-job.ts"), "utf8"),
    };
}

function idempotencyKey(loaded: Loaded, sides: Array<"left" | "right">): string {
    const anchor = sides[0] ?? "left";
    const identity = loaded.identity({
        designId: DESIGN_ID,
        side: anchor,
        presetId: loaded.presetId,
        useSavedDesignMesh: true,
        material: loaded.canonicalMaterial(FIXTURE_MATERIAL),
        beltAngleDeg: 0,
        layerHeightMm: null,
        printRecipe: loaded.recipe(loaded.settingsJson),
        settingsJson: loaded.settingsJson,
        stlStorageKey: null,
        deliverable: "cnc_gcode",
        millSides: sides,
    });
    const sideKey = sides.length === 1 ? sides[0] : "pair";
    return `cadop:v1:${DESIGN_ID}:${sideKey}:${loaded.presetId}:${identity.fingerprint}`;
}

async function parseGenerateInput(repo: string, raw: Record<string, unknown>): Promise<Record<string, unknown>> {
    const mod = await import(pathToFileURL(join(repo, "vertex/server/src/routers/manufacturing.ts")).href);
    const proc = mod.manufacturingRouter.generateCncGcode as { _def: { inputs: Array<{ parseAsync: (value: unknown) => Promise<unknown> }> } };
    let value: unknown = raw;
    for (const schema of proc._def.inputs) value = await schema.parseAsync(value);
    return value as Record<string, unknown>;
}

interface MeasuredPaths {
    wiring: { prepare: boolean; filename: boolean; build: boolean };
    zod: {
        rr: unknown;
        ll: unknown;
        lr: unknown;
        omitted: unknown;
        rxThrew: boolean;
    };
    prepareSides: Record<"RR" | "LL" | "LR" | "omit", Array<"left" | "right">>;
    filenames: Record<"RR" | "LL" | "LR" | "omit", string>;
    keys: Record<"RR" | "LL" | "LR" | "omit", string>;
    gcode: Record<"RR" | "LL" | "LR" | "omit", { sha256: string; bytes: number }>;
    browser: Record<"RR" | "LL", { sha256: string; bytes: number }>;
    helper: { rr: string; ll: string };
    normalize: Record<string, string>;
    thicknessUnmarked: { left: number; right: number };
    thicknessMarked: { left: number; right: number };
    profile: ProfileSnap;
    clearanceMm: number;
    size15: { lengthMm: number; widthMm: number; xMarginMm: number; yMarginMm: number };
    files: Record<string, string>;
    diff: string[];
    phiHits: string[];
    guards: Record<string, boolean>;
    tests: { exitCode: number | null; summary: string };
}

function hashGcode(gcode: string): { sha256: string; bytes: number } {
    const bytes = Buffer.byteLength(gcode);
    return { sha256: sha256(gcode), bytes };
}

async function serverBuild(
    loaded: Loaded,
    design: unknown,
    mode: "RR" | "LL" | "LR" | "omit",
    wired: boolean,
): Promise<{ gcode: string; sides: Array<"left" | "right"> }> {
    if (!wired) return loaded.buildServer(design);
    if (mode === "omit") return loaded.buildServer(design, { millSide: undefined });
    return loaded.buildServer(design, { millSide: mode });
}

async function serverPrepare(
    loaded: Loaded,
    mode: "RR" | "LL" | "LR" | "omit",
    wired: boolean,
): Promise<Array<"left" | "right">> {
    if (!wired) {
        const prepared = await loaded.prepare(loaded.doc);
        return prepared.sides;
    }
    if (mode === "omit") {
        const prepared = await loaded.prepare(loaded.doc, { millSide: undefined });
        return prepared.sides;
    }
    const prepared = await loaded.prepare(loaded.doc, { millSide: mode });
    return prepared.sides;
}

function filenameFor(
    loaded: Loaded,
    sides: Array<"left" | "right">,
    mode: "RR" | "LL" | "LR" | "omit",
    wired: boolean,
): string {
    return loaded.filename({
        firstName: FIXTURE_FIRST,
        lastName: FIXTURE_LAST,
        material: FIXTURE_MATERIAL,
        sides,
        ...(wired && mode !== "omit" ? { millSide: mode } : {}),
    });
}

async function measure(repo: string, withTests: boolean): Promise<MeasuredPaths> {
    const loaded = await loadProduct(repo);
    const requestFn = extractFunction(loaded.requestSource, "runCadOperatorCncGcodeRequest");
    const wiring = {
        prepare: passesInputMillSide(requestFn, "prepareHeadlessMillDesign"),
        filename: passesInputMillSide(requestFn, "cncPairGcodeFilename"),
        build: passesInputMillSide(requestFn, "buildHeadlessMillCncGcode"),
    };
    const designId = DESIGN_ID;
    const zod = {
        rr: (await parseGenerateInput(repo, { designId, material: FIXTURE_MATERIAL, millSide: "RR" })).millSide,
        ll: (await parseGenerateInput(repo, { designId, material: FIXTURE_MATERIAL, millSide: "LL" })).millSide,
        lr: (await parseGenerateInput(repo, { designId, material: FIXTURE_MATERIAL, millSide: "LR" })).millSide,
        omitted: (await parseGenerateInput(repo, { designId, material: FIXTURE_MATERIAL })).millSide,
        rxThrew: false,
    };
    try {
        await parseGenerateInput(repo, { designId, material: FIXTURE_MATERIAL, millSide: "RX" });
    } catch {
        zod.rxThrew = true;
    }

    const prepareSides = {
        RR: await serverPrepare(loaded, "RR", wiring.prepare),
        LL: await serverPrepare(loaded, "LL", wiring.prepare),
        LR: await serverPrepare(loaded, "LR", wiring.prepare),
        omit: await serverPrepare(loaded, "omit", wiring.prepare),
    };
    const prepared = await loaded.prepare(loaded.doc);
    const filenames = {
        RR: filenameFor(loaded, prepareSides.RR, "RR", wiring.filename),
        LL: filenameFor(loaded, prepareSides.LL, "LL", wiring.filename),
        LR: filenameFor(loaded, prepareSides.LR, "LR", wiring.filename),
        omit: filenameFor(loaded, prepareSides.omit, "omit", wiring.filename),
    };
    const keys = {
        RR: idempotencyKey(loaded, prepareSides.RR),
        LL: idempotencyKey(loaded, prepareSides.LL),
        LR: idempotencyKey(loaded, prepareSides.LR),
        omit: idempotencyKey(loaded, prepareSides.omit),
    };
    const gcode = {
        omit: hashGcode((await serverBuild(loaded, prepared.design, "omit", wiring.build)).gcode),
        LR: hashGcode((await serverBuild(loaded, prepared.design, "LR", wiring.build)).gcode),
        RR: hashGcode((await serverBuild(loaded, prepared.design, "RR", wiring.build)).gcode),
        LL: hashGcode((await serverBuild(loaded, prepared.design, "LL", wiring.build)).gcode),
    };
    const browserRr = await loaded.buildBrowser({ design: loaded.hydrated, millSide: "RR" });
    const browserLl = await loaded.buildBrowser({ design: loaded.hydrated, millSide: "LL" });
    const browser = { RR: hashGcode(browserRr.gcode), LL: hashGcode(browserLl.gcode) };

    const marked = {
        thicknessMm: THICKNESS_MARKED_MM,
        paired: { leftThicknessMm: THICKNESS_MARKED_MM, rightThicknessMm: THICKNESS_MARKED_MM },
    };
    const unmarked = {
        thicknessMm: THICKNESS_UNMARKED_MM,
        paired: { leftThicknessMm: THICKNESS_UNMARKED_MM, rightThicknessMm: THICKNESS_UNMARKED_MM },
    };
    const widthExtent = loaded.layout15.widthMm + loaded.profile.toolpathCutter.diameterMm;
    const lengthExtent = loaded.layout15.lengthMm + loaded.profile.toolpathCutter.diameterMm;
    const pocketY = loaded.profile.pockets[0]?.length ?? 0;
    const yMargin = pocketY - 2 * loaded.clearanceMm - widthExtent;
    const xMargin = loaded.profile.tableWidthMm - 2 * loaded.clearanceMm - lengthExtent;
    const files: Record<string, string> = {};
    for (const rel of [...new Set([...SURFACE_FILES, ...THICKNESS_FILES, ...CLEARANCE_FILES])]) {
        files[rel] = fileSha(repo, rel);
    }
    const gen = procedureSlice(loaded.manufacturingSource, "generateCncGcode");
    const guards = {
        prepareAssert: loaded.runnerSource.includes("assertMilledCncOrder("),
        prepareCall: /assertMilledCncOrder\(/.test(extractFunction(loaded.runnerSource, "prepareHeadlessMillDesign")),
        buildCall: /assertMilledCncOrder\(/.test(extractFunction(loaded.runnerSource, "buildHeadlessMillCncGcode")),
        printRefusal: loaded.millJobSource.includes("Print orders are not CNC G-code"),
        uuid: gen.includes("designId: z.string().uuid()"),
        rateLimit: gen.includes("rateLimitedSessionOrCadProcedure"),
        credential: gen.includes('message: "CAD-operator credential required"') && gen.includes("if (!ctx.cadOperator)"),
    };
    const phiPattern = /console\.(log|debug|info|warn|error)\([^)\n]*(firstName|lastName|patientName|dateOfBirth)/;
    const secretPattern = /api[_-]?key|service_role|BEGIN [A-Z ]*PRIVATE/i;
    const phiHits = addedLines(repo)
        .filter((line) => phiPattern.test(line) || secretPattern.test(line))
        .map((line) => (phiPattern.test(line) ? "added log reads client name field" : "added secret material"));
    const diff = productDiff(repo);
    let tests: { exitCode: number | null; summary: string } = { exitCode: null, summary: "not-run" };
    if (withTests) {
        const bin = join(repo, "node_modules/.bin/rstest");
        const ran = spawnSync(bin, ["vertex/server/src/lib/cnc-mill-gcode.test.ts"], {
            cwd: repo,
            encoding: "utf8",
            timeout: 240_000,
        });
        const text = redact(`${ran.stdout ?? ""}\n${ran.stderr ?? ""}`);
        const summaryLines = text
            .split("\n")
            .map((line) => line.trim())
            .filter((line) => /Test Files|Tests |FAIL|PASS|passed|failed/.test(line));
        tests = {
            exitCode: ran.status,
            summary: summaryLines.slice(-8).join(" | ") || `exit ${ran.status}`,
        };
    }
    return {
        wiring,
        zod,
        prepareSides,
        filenames,
        keys,
        gcode,
        browser,
        helper: {
            rr: loaded.internalSide(loaded.hydrated, "right"),
            ll: loaded.internalSide(loaded.hydrated, "left"),
        },
        normalize: {
            RR: loaded.normalize("RR"),
            LL: loaded.normalize("LL"),
            LR: loaded.normalize("LR"),
            omit: loaded.normalize(undefined),
            RX: loaded.normalize("RX"),
        },
        thicknessUnmarked: {
            left: loaded.thickness(unmarked, "left"),
            right: loaded.thickness(unmarked, "right"),
        },
        thicknessMarked: {
            left: loaded.thickness(marked, "left"),
            right: loaded.thickness(marked, "right"),
        },
        profile: loaded.profile,
        clearanceMm: loaded.clearanceMm,
        size15: {
            lengthMm: round3(loaded.layout15.lengthMm),
            widthMm: round3(loaded.layout15.widthMm),
            xMarginMm: round3(xMargin),
            yMarginMm: round3(yMargin),
        },
        files,
        diff,
        phiHits,
        guards,
        tests,
    };
}

function round3(n: number): number {
    return Math.round(n * 1000) / 1000;
}

function evaluate(measured: MeasuredPaths, baseline: Baseline): GateResult[] {
    const outOfScope = measured.diff.filter((path) => !ALLOWLIST.has(path));
    const surfaceDrift = SURFACE_FILES.filter((rel) => measured.files[rel] !== baseline.fileSha256[rel]);
    const thicknessDrift = THICKNESS_FILES.filter((rel) => measured.files[rel] !== baseline.fileSha256[rel]);
    const clearanceDrift = CLEARANCE_FILES.filter((rel) => measured.files[rel] !== baseline.fileSha256[rel]);
    const guardsOk = Object.values(measured.guards).every(Boolean);
    return [
        gate(
            "defect_zod_rr",
            "R1 ONE",
            measured.zod.rr === "RR",
            measured.zod.rr ?? null,
            "RR",
            "generateCncGcode input keeps millSide RR",
        ),
        gate(
            "defect_zod_ll",
            "R1 ONE",
            measured.zod.ll === "LL",
            measured.zod.ll ?? null,
            "LL",
            "generateCncGcode input keeps millSide LL",
        ),
        gate(
            "defect_zod_rejects_rx",
            "ONE",
            measured.zod.rxThrew,
            measured.zod.rxThrew,
            true,
            "generateCncGcode rejects millSide outside LR|RR|LL",
        ),
        gate(
            "keep_zod_lr_omitted",
            "R6 MUST-MATCH",
            (measured.zod.lr === undefined || measured.zod.lr === "LR") &&
                (measured.zod.omitted === undefined || measured.zod.omitted === "LR"),
            { lr: measured.zod.lr ?? null, omitted: measured.zod.omitted ?? null },
            "undefined or LR",
            "omitted and LR stay accepted on the server input",
        ),
        gate(
            "defect_wiring",
            "ONE",
            measured.wiring.prepare && measured.wiring.filename && measured.wiring.build,
            measured.wiring,
            { prepare: true, filename: true, build: true },
            "runCadOperatorCncGcodeRequest passes args.input.millSide into prepare, filename, and build",
        ),
        gate(
            "defect_sides_rr",
            "R1 TESTS",
            sameJson(measured.prepareSides.RR, EXPECT_RR_SIDES) && measured.helper.rr === "left",
            { sides: measured.prepareSides.RR, internalRight: measured.helper.rr },
            { sides: EXPECT_RR_SIDES, internalRight: "left" },
            "RR on a two-foot milled SAMPLE_Top design returns [internal-right, internal-right]",
        ),
        gate(
            "defect_sides_ll",
            "R1 TESTS",
            sameJson(measured.prepareSides.LL, EXPECT_LL_SIDES) && measured.helper.ll === "right",
            { sides: measured.prepareSides.LL, internalLeft: measured.helper.ll },
            { sides: EXPECT_LL_SIDES, internalLeft: "right" },
            "LL returns [internal-left, internal-left]",
        ),
        gate(
            "defect_filename_rr",
            "TESTS",
            measured.filenames.RR.endsWith("_EVA_RR.gcode"),
            fileSuffix(measured.filenames.RR),
            "_EVA_RR.gcode",
            "EVA Milled filename suffix for millSide RR",
        ),
        gate(
            "defect_filename_ll",
            "TESTS",
            measured.filenames.LL.endsWith("_EVA_LL.gcode"),
            fileSuffix(measured.filenames.LL),
            "_EVA_LL.gcode",
            "EVA Milled filename suffix for millSide LL",
        ),
        gate(
            "defect_idempotency_rr",
            "TESTS ONE",
            measured.keys.RR !== measured.keys.LR && measured.keys.RR !== baseline.lrIdempotencyKey,
            { rr: measured.keys.RR, lr: measured.keys.LR },
            "RR key differs from LR and from main LR key",
            "RR gets its own idempotency key",
        ),
        gate(
            "defect_idempotency_ll",
            "TESTS ONE",
            measured.keys.LL !== measured.keys.LR && measured.keys.LL !== measured.keys.RR,
            { ll: measured.keys.LL, lr: measured.keys.LR, rr: measured.keys.RR },
            "LL key differs from LR and from RR",
            "LL gets its own idempotency key",
        ),
        gate(
            "defect_gcode_rr",
            "TESTS",
            measured.gcode.RR.sha256 === measured.browser.RR.sha256 && measured.gcode.RR.bytes === measured.browser.RR.bytes,
            { server: measured.gcode.RR, browser: measured.browser.RR },
            "sha256 equal and byte length equal",
            "server RR G-code bytes equal browser buildMillCncGcode millSide RR",
        ),
        gate(
            "defect_gcode_ll",
            "TESTS",
            measured.gcode.LL.sha256 === measured.browser.LL.sha256 && measured.gcode.LL.bytes === measured.browser.LL.bytes,
            { server: measured.gcode.LL, browser: measured.browser.LL },
            "sha256 equal and byte length equal",
            "server LL G-code bytes equal browser buildMillCncGcode millSide LL",
        ),
        gate(
            "keep_lr_sides",
            "R6 MUST-MATCH",
            sameJson(measured.prepareSides.LR, baseline.lrSides) && sameJson(measured.prepareSides.omit, baseline.lrSides),
            { lr: measured.prepareSides.LR, omit: measured.prepareSides.omit },
            baseline.lrSides,
            "omitted and LR sides stay the main pair",
        ),
        gate(
            "keep_lr_filename",
            "R6 MUST-MATCH",
            measured.filenames.LR === baseline.lrFilename && measured.filenames.omit === baseline.lrFilename,
            { lr: fileSuffix(measured.filenames.LR), omit: fileSuffix(measured.filenames.omit) },
            fileSuffix(baseline.lrFilename),
            "omitted and LR filename suffix stays the main suffix",
        ),
        gate(
            "keep_lr_idempotency",
            "R6 MUST-MATCH",
            measured.keys.LR === baseline.lrIdempotencyKey && measured.keys.omit === baseline.lrIdempotencyKey,
            { lr: measured.keys.LR, omit: measured.keys.omit },
            baseline.lrIdempotencyKey,
            "omitted and LR idempotency key stays the main key",
        ),
        gate(
            "keep_lr_gcode",
            "R6 MUST-MATCH",
            measured.gcode.LR.sha256 === baseline.lrGcodeSha256 &&
                measured.gcode.omit.sha256 === baseline.lrGcodeSha256 &&
                measured.gcode.LR.bytes === baseline.lrGcodeBytes &&
                measured.gcode.omit.bytes === baseline.lrGcodeBytes,
            { lr: measured.gcode.LR, omit: measured.gcode.omit },
            { sha256: baseline.lrGcodeSha256, bytes: baseline.lrGcodeBytes },
            "omitted and LR G-code bytes stay identical to main",
        ),
        gate(
            "keep_profile_r6",
            "R6",
            sameJson(measured.profile, baseline.profile),
            {
                id: measured.profile.id,
                strategy: measured.profile.strategy,
                stepoverBallMm: measured.profile.stepoverBallMm,
                stepoverFlatMm: measured.profile.stepoverFlatMm,
                layeredMm: measured.profile.layeredMm,
                toolpathCutter: measured.profile.toolpathCutter,
                topFeeds: measured.profile.topFeeds,
                bottomFeeds: measured.profile.bottomFeeds,
            },
            {
                id: baseline.profile.id,
                strategy: baseline.profile.strategy,
                stepoverBallMm: baseline.profile.stepoverBallMm,
                stepoverFlatMm: baseline.profile.stepoverFlatMm,
                layeredMm: baseline.profile.layeredMm,
                toolpathCutter: baseline.profile.toolpathCutter,
                topFeeds: baseline.profile.topFeeds,
                bottomFeeds: baseline.profile.bottomFeeds,
            },
            "cutter, feeds, stepover, and strategy stay the main Idaho profile",
        ),
        gate(
            "keep_normalize_mill_side",
            "ONE",
            measured.normalize.RR === "RR" &&
                measured.normalize.LL === "LL" &&
                measured.normalize.LR === "LR" &&
                measured.normalize.omit === "LR" &&
                measured.normalize.RX === "LR",
            measured.normalize,
            { RR: "RR", LL: "LL", LR: "LR", omit: "LR", RX: "LR" },
            "reuse normalizeMillSide; unknown values stay LR",
        ),
        gate(
            "keep_r2_thickness",
            "R2",
            measured.thicknessUnmarked.left >= R2_MIN_MM &&
                measured.thicknessUnmarked.right >= R2_MIN_MM &&
                measured.thicknessUnmarked.left === baseline.thicknessUnmarkedMm.left &&
                measured.thicknessUnmarked.right === baseline.thicknessUnmarkedMm.right,
            measured.thicknessUnmarked,
            { minMm: R2_MIN_MM, baseline: baseline.thicknessUnmarkedMm },
            "unmarked EVA mill thickness stays >= 4.0 mm on both feet",
        ),
        gate(
            "keep_r2_marked",
            "R2",
            measured.thicknessMarked.left === THICKNESS_MARKED_MM &&
                measured.thicknessMarked.right === THICKNESS_MARKED_MM,
            measured.thicknessMarked,
            { left: THICKNESS_MARKED_MM, right: THICKNESS_MARKED_MM },
            "a thickness marked otherwise stays that thickness",
        ),
        gate(
            "keep_r2_files",
            "R2 R7",
            thicknessDrift.length === 0,
            thicknessDrift,
            [],
            "thickness implementation files match main",
        ),
        gate(
            "keep_r3_clearance",
            "R3",
            measured.clearanceMm === R3_CLEARANCE_MM && measured.clearanceMm === baseline.clearanceMm && clearanceDrift.length === 0,
            { clearanceMm: measured.clearanceMm, drifted: clearanceDrift },
            { clearanceMm: R3_CLEARANCE_MM, drifted: [] },
            "toolpath clearance stays 1 mm and the clearance sources match main",
        ),
        gate(
            "keep_r3_size15_fit",
            "R3",
            measured.size15.xMarginMm >= 0 &&
                measured.size15.yMarginMm >= 0 &&
                sameJson(measured.size15, baseline.size15),
            measured.size15,
            { ...baseline.size15, xMarginMm: ">= 0", yMarginMm: ">= 0" },
            "US men size 15 tool envelope fits the block with clearance; cutouts stay apart",
        ),
        gate(
            "keep_r4_scope",
            "R4",
            outOfScope.length === 0,
            { changed: measured.diff, outOfScope },
            { outOfScope: [] },
            "product edits stay on the millSide server wiring allowlist",
        ),
        gate(
            "keep_r5_phi",
            "R5",
            measured.phiHits.length === 0 &&
                !measured.diff.some((path) => /railway|vertex-web|vertex-api|prisma\/migrations/i.test(path)),
            { hits: measured.phiHits.length, forbiddenPaths: measured.diff.filter((path) => /railway|vertex-web|vertex-api|prisma\/migrations/i.test(path)) },
            { hits: 0, forbiddenPaths: [] },
            "no new name-field logs, secrets, Railway, vertex-web, vertex-api, or migrations",
        ),
        gate(
            "keep_r7_surface",
            "R7",
            surfaceDrift.length === 0 && measured.gcode.LR.sha256 === baseline.lrGcodeSha256,
            { drifted: surfaceDrift, lrSha256: measured.gcode.LR.sha256 },
            { drifted: [], lrSha256: baseline.lrGcodeSha256 },
            "surface, seam, and layer-change sources match main and LR toolpath bytes match",
        ),
        gate(
            "keep_safety_guards",
            "TESTS",
            guardsOk,
            measured.guards,
            {
                prepareAssert: true,
                prepareCall: true,
                buildCall: true,
                printRefusal: true,
                uuid: true,
                rateLimit: true,
                credential: true,
            },
            "print-order refusal, design id check, rate limit, and CAD-operator credential check stay",
        ),
        gate(
            "keep_existing_tests",
            "TESTS",
            measured.tests.exitCode === 0,
            { exitCode: measured.tests.exitCode, summary: measured.tests.summary },
            { exitCode: 0 },
            "vertex/server/src/lib/cnc-mill-gcode.test.ts passes",
        ),
    ];
}

function referenceFrom(measured: MeasuredPaths): Baseline {
    const files: Record<string, string> = {};
    for (const rel of [...new Set([...SURFACE_FILES, ...THICKNESS_FILES, ...CLEARANCE_FILES])]) {
        files[rel] = measured.files[rel] ?? "";
    }
    return {
        baseSha: BASE_SHA,
        lrGcodeSha256: measured.gcode.omit.sha256,
        lrGcodeBytes: measured.gcode.omit.bytes,
        lrFilename: measured.filenames.omit,
        lrIdempotencyKey: measured.keys.omit,
        lrSides: measured.prepareSides.omit,
        profile: measured.profile,
        fileSha256: files,
        thicknessUnmarkedMm: measured.thicknessUnmarked,
        thicknessMarkedMm: measured.thicknessMarked,
        clearanceMm: measured.clearanceMm,
        size15: measured.size15,
    };
}

function readBaseline(): Baseline {
    return JSON.parse(readFileSync(baselinePath(), "utf8")) as Baseline;
}

function writeJson(path: string, value: unknown): void {
    mkdirSync(dirname(path), { recursive: true });
    writeFileSync(path, `${JSON.stringify(value, null, 2)}\n`);
}

async function grade(withTests: boolean): Promise<GateResult[]> {
    const measured = await measure(repoRoot(), withTests);
    return evaluate(measured, readBaseline());
}

function summarize(results: GateResult[]): string {
    return results.map((row) => `${row.pass ? "PASS" : "FAIL"} ${row.id} measured=${JSON.stringify(row.measured)} threshold=${JSON.stringify(row.threshold)}`).join("\n");
}

function replaceOnce(path: string, from: string, to: string): void {
    const source = readFileSync(path, "utf8");
    const hits = source.split(from).length - 1;
    if (hits !== 1) throw new Error(`expected 1 match in ${path}, found ${hits}`);
    writeFileSync(path, source.replace(from, to));
}

function applyBadChange(repo: string): void {
    replaceOnce(
        join(repo, "vertex/server/src/routers/manufacturing.ts"),
        `        .input(
            z.object({
                designId: z.string().uuid(),
                material: z.string().trim().min(1).max(80).optional(),
            }),
        )
        .mutation(async ({ ctx, input }) => {
            if (!ctx.cadOperator) {
                throw new TRPCError({ code: "FORBIDDEN", message: "CAD-operator credential required" });
            }
            return runCadOperatorCncGcodeRequest({
                prisma: ctx.prisma,
                principal: ctx.cadOperator,
                ip: ctx.ip,
                input,
            });
        }),`,
        `        .input(
            z.object({
                designId: z.string().min(1),
                material: z.string().trim().min(1).max(80).optional(),
                millSide: z.any().optional().transform(() => "NO" as const),
            }),
        )
        .mutation(async ({ input }) => {
            return runCadOperatorCncGcodeRequest({
                prisma: undefined as never,
                principal: undefined as never,
                ip: null,
                input,
            });
        }),`,
    );
    replaceOnce(
        join(repo, "vertex/server/src/routers/cad-operator-generate.ts"),
        `    fileExtension: string;
}> {
    const { row, design } = await loadDogfoodDesign(args.prisma, args.principal, args.input.designId);`,
        `    fileExtension: string;
}> {
    const { row, design } = await loadDogfoodDesign(args.prisma, args.principal, args.input.designId);
    console.log(row.client.firstName);`,
    );
    replaceOnce(
        join(repo, "vertex/server/src/lib/cnc-mill-runner.ts"),
        `    mod.assertMilledCncOrder(design);
    return { design, sides: mod.millExportSides(design) };`,
        `    return { design, sides: ["left"] };`,
    );
    replaceOnce(
        join(repo, "vertex/server/src/lib/cnc-mill-runner.ts"),
        `    mod.assertMilledCncOrder(design as MillDesign);
    installBundledSampleTopFetch(await bundledSampleTop());
    const { Cache } = await import("three");
    Cache.clear();
    return mod.buildMillCncGcode({ design });`,
        `    installBundledSampleTopFetch(await bundledSampleTop());
    const { Cache } = await import("three");
    Cache.clear();
    const built = await mod.buildMillCncGcode({ design });
    return { ...built, gcode: \`\${built.gcode}\\n; bad-change\\n\`, sides: ["left", "right"] };`,
    );
    replaceOnce(
        join(repo, "vertex/src/lib/cnc/order-sides.ts"),
        `export function normalizeMillSide(value: string | null | undefined): MillSide {
    if (value === "RR" || value === "LL" || value === "LR") return value;
    return "LR";
}`,
        `export function normalizeMillSide(_value: string | null | undefined): MillSide {
    return "LR";
}`,
    );
    replaceOnce(join(repo, "vertex/src/lib/cnc/profile.ts"), "stepoverBallMm: 1.4,", "stepoverBallMm: 9.9,");
    replaceOnce(join(repo, "vertex/src/lib/cnc/envelope.ts"), "export const ENVELOPE_CLEARANCE_MM = 1;", "export const ENVELOPE_CLEARANCE_MM = 0;");
    replaceOnce(
        join(repo, "vertex/src/lib/geometry/shape-finish-modifiers.ts"),
        `export function thicknessMmForDesignSide(design: DesignState, side: Side): number {
    if (design.paired) {`,
        `export function thicknessMmForDesignSide(design: DesignState, side: Side): number {
    return 1;
    if (design.paired) {`,
    );
    replaceOnce(
        join(repo, "vertex/src/lib/cnc/export.ts"),
        "export function generateCncJob(",
        "// bad-change: layer change moved off the plantar face\nexport function generateCncJob(",
    );
}

function proveBad(): GateResult[] {
    const repo = repoRoot();
    const wt = mkdtempSync(join(tmpdir(), "mill-side-bad-"));
    try {
        execFileSync("git", ["worktree", "add", "--detach", wt, BASE_SHA], { cwd: repo, stdio: "inherit" });
        symlinkSync(join(repo, "node_modules"), join(wt, "node_modules"));
        symlinkSync(join(repo, "vertex/node_modules"), join(wt, "vertex/node_modules"));
        applyBadChange(wt);
        const tsx = join(repo, "vertex/node_modules/.bin/tsx");
        const ran = spawnSync(tsx, ["--tsconfig", join(wt, "vertex/tsconfig.json"), fileURLToPath(import.meta.url), "grade"], {
            cwd: wt,
            env: { ...process.env, GATE_REPO: wt, GATE_BASELINE: baselinePath() },
            encoding: "utf8",
            timeout: 300_000,
        });
        const text = redact(`${ran.stdout ?? ""}\n${ran.stderr ?? ""}`);
        const start = text.lastIndexOf("GATE_JSON_BEGIN");
        const end = text.lastIndexOf("GATE_JSON_END");
        if (ran.status !== 0 || start < 0 || end < start) {
            throw new Error(`bad-change grade failed to emit results (exit ${ran.status})\n${text.slice(-2000)}`);
        }
        return JSON.parse(text.slice(start + "GATE_JSON_BEGIN".length, end)) as GateResult[];
    } finally {
        execFileSync("git", ["worktree", "remove", "--force", wt], { cwd: repo, stdio: "ignore" });
        rmSync(wt, { recursive: true, force: true });
    }
}

async function main(): Promise<void> {
    const cmd = process.argv[2];
    if (cmd === "capture-baseline") {
        const measured = await measure(repoRoot(), false);
        const baseline = referenceFrom(measured);
        writeJson(baselinePath(), baseline);
        process.stdout.write(`captured ${baselinePath()}\nlrBytes=${baseline.lrGcodeBytes} lrSha=${baseline.lrGcodeSha256}\n`);
        return;
    }
    if (cmd === "grade") {
        const results = await grade(true);
        process.stdout.write(`${summarize(results)}\nGATE_JSON_BEGIN\n${JSON.stringify(results)}\nGATE_JSON_END\n`);
        return;
    }
    if (cmd === "prove-noop") {
        const results = await grade(true);
        const defect = results.filter((row) => row.id.startsWith("defect_"));
        const keep = results.filter((row) => row.id.startsWith("keep_"));
        const ok = defect.every((row) => !row.pass) && keep.every((row) => row.pass) && defect.length > 0 && keep.length > 0;
        writeJson(join(GATE_DIR, "proofs/noop.json"), {
            baseSha: BASE_SHA,
            ok,
            defectFailed: defect.filter((row) => !row.pass).map((row) => row.id),
            keepFailed: keep.filter((row) => !row.pass).map((row) => row.id),
            results,
        });
        process.stdout.write(`${summarize(results)}\nnoop ${ok ? "OK" : "NOT-OK"}\n`);
        process.exit(ok ? 0 : 1);
    }
    if (cmd === "prove-bad") {
        const results = proveBad();
        const ok = results.length > 0 && results.every((row) => !row.pass);
        writeJson(join(GATE_DIR, "proofs/bad.json"), {
            baseSha: BASE_SHA,
            ok,
            stillPassing: results.filter((row) => row.pass).map((row) => row.id),
            results,
        });
        process.stdout.write(`${summarize(results)}\nbad ${ok ? "OK" : "NOT-OK"}\n`);
        process.exit(ok ? 0 : 1);
    }
    throw new Error(`unknown command ${cmd ?? ""}`);
}

main().catch((error: unknown) => {
    const message = error instanceof Error ? error.message : String(error);
    process.stderr.write(`${redact(message)}\n`);
    process.exit(1);
});
